const MANIFEST = {
  "type": "Social.ReviewRail",
  "description": "Continuous marquee of customer reviews with star ratings and an aggregate score. Pauses on hover, drag to scrub.",
  "editorElement": {
    "selector": ".review-rail",
    "displayName": "Review Rail",
    "archetype": "container",
    "data": {
      "sectionLabel": { "dataType": "text", "displayName": "Section Label", "defaultValue": "What people say", "group": "Content" },
      "heading": { "dataType": "text", "displayName": "Heading", "defaultValue": "1,240 reviews and counting", "group": "Content" },
      "aggregateScore": { "dataType": "text", "displayName": "Aggregate Score", "defaultValue": "4.9", "group": "Content" },
      "aggregateSource": { "dataType": "text", "displayName": "Score Source", "defaultValue": "Average across Google and Trustpilot", "group": "Content" },
      "showAggregate": { "dataType": "booleanValue", "displayName": "Show Aggregate Score", "defaultValue": true, "group": "Content" },
      "reviews": {
        "dataType": "text",
        "displayName": "Reviews (Name|Rating|Text|Meta, separated by ;)",
        "defaultValue": "Hannah M.|5|Booked on a Tuesday, seen on a Wednesday. The whole thing took ten minutes and nobody tried to upsell me.|Verified customer;David O.|5|Third year with them. Same team every visit, which is the entire reason I stay.|Google review;Priya S.|4|Slight wait on arrival but they were upfront about it and knocked something off. Fair.|Trustpilot;Marcus L.|5|Quoted a price, charged the price. You would not believe how rare that is.|Verified customer;Elena R.|5|They fixed in one visit what two other places could not diagnose.|Google review",
        "group": "Content",
        "description": "One review per ; — fields split by |"
      },
      "speed": { "dataType": "select", "displayName": "Scroll Duration (s)", "defaultValue": "46", "options": ["26", "36", "46", "60", "80"], "group": "Animation" },
      "direction": { "dataType": "select", "displayName": "Direction", "defaultValue": "left", "options": ["left", "right"], "group": "Animation" },
      "pauseOnHover": { "dataType": "booleanValue", "displayName": "Pause on Hover", "defaultValue": true, "group": "Animation" },
      "cardWidth": { "dataType": "select", "displayName": "Card Width (px)", "defaultValue": "340", "options": ["280", "310", "340", "400", "460"], "group": "Layout" },
      "edgeFade": { "dataType": "booleanValue", "displayName": "Fade Edges", "defaultValue": true, "group": "Layout" },
      "backgroundColor": { "dataType": "color", "displayName": "Background", "defaultValue": "#F6F5F2", "group": "Colors" },
      "cardColor": { "dataType": "color", "displayName": "Card Background", "defaultValue": "#FFFFFF", "group": "Colors" },
      "textColor": { "dataType": "color", "displayName": "Text", "defaultValue": "#1A1A1A", "group": "Colors" },
      "mutedColor": { "dataType": "color", "displayName": "Muted Text", "defaultValue": "#6B6B6B", "group": "Colors" },
      "starColor": { "dataType": "color", "displayName": "Stars", "defaultValue": "#C2803A", "group": "Colors" },
      "borderColor": { "dataType": "color", "displayName": "Card Border", "defaultValue": "#E3E1DB", "group": "Colors" },
      "headingSize": { "dataType": "number", "displayName": "Heading Size (px)", "defaultValue": 34, "group": "Typography" },
      "quoteSize": { "dataType": "number", "displayName": "Review Size (px)", "defaultValue": 15, "group": "Typography" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config = {} }) {
  const bg = config?.backgroundColor || '#F6F5F2';
  const card = config?.cardColor || '#FFFFFF';
  const text = config?.textColor || '#1A1A1A';
  const muted = config?.mutedColor || '#6B6B6B';
  const star = config?.starColor || '#C2803A';
  const border = config?.borderColor || '#E3E1DB';
  const cardW = parseInt(config?.cardWidth || '340', 10);
  const speed = parseInt(config?.speed || '46', 10);
  const rtl = (config?.direction || 'left') === 'right';
  const pauseOnHover = config?.pauseOnHover !== false;
  const edgeFade = config?.edgeFade !== false;
  const showAggregate = config?.showAggregate !== false;
  const headingSize = Math.max(16, Math.min(80, parseInt(config?.headingSize, 10) || 34));
  const quoteSize = Math.max(11, Math.min(26, parseInt(config?.quoteSize, 10) || 15));

  const reviews = (config?.reviews || '').split(';').map(function (chunk) {
    const f = chunk.split('|');
    const r = parseFloat(f[1]);
    return {
      name: (f[0] || '').trim(),
      rating: isNaN(r) ? 5 : Math.max(0, Math.min(5, Math.round(r))),
      text: (f[2] || '').trim(),
      meta: (f[3] || '').trim()
    };
  }).filter(function (r) { return r.name && r.text; });

  const [paused, setPaused] = React.useState(false);
  const uid = React.useRef('rr' + Math.random().toString(36).slice(2, 8)).current;

  const reduceMotion = typeof window !== 'undefined' && window.matchMedia
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

  const Stars = function (props) {
    return (
      <span aria-label={props.n + ' out of 5'} style={{ display: 'inline-flex', gap: '2px' }}>
        {[0, 1, 2, 3, 4].map(function (i) {
          return (
            <svg key={i} width="13" height="13" viewBox="0 0 24 24" aria-hidden="true"
                 fill={i < props.n ? star : 'none'} stroke={star} strokeWidth="1.6">
              <path d="M12 2.6l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.4l-5.8 3.1 1.1-6.5L2.6 9.4l6.5-.9z" />
            </svg>
          );
        })}
      </span>
    );
  };

  const cards = reviews.concat(reviews);   // duplicated for a seamless loop

  return (
    <div className="review-rail" style={{
      backgroundColor: bg, color: text, width: '100%', padding: '72px 0', overflow: 'hidden',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
      WebkitFontSmoothing: 'antialiased'
    }}>
      <style>{
        '@keyframes ' + uid + '{from{transform:translateX(0)}to{transform:translateX(-50%)}}' +
        '.' + uid + '-track{display:flex;gap:18px;width:max-content;' +
        'animation:' + uid + ' ' + speed + 's linear infinite;' +
        (rtl ? 'animation-direction:reverse;' : '') + '}' +
        '@media (prefers-reduced-motion: reduce){.' + uid + '-track{animation:none}}'
      }</style>

      <div style={{ maxWidth: '1180px', margin: '0 auto', padding: '0 40px 34px' }}>
        {config?.sectionLabel ? (
          <p style={{
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: '11px',
            letterSpacing: '0.14em', textTransform: 'uppercase', color: muted, margin: '0 0 12px'
          }}>{config.sectionLabel}</p>
        ) : null}
        <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: '24px', flexWrap: 'wrap' }}>
          {config?.heading ? (
            <h2 style={{
              fontSize: headingSize + 'px', fontWeight: 500, lineHeight: 1.1,
              letterSpacing: '-0.02em', margin: 0, maxWidth: '20ch', textWrap: 'balance'
            }}>{config.heading}</h2>
          ) : <span />}
          {showAggregate && config?.aggregateScore ? (
            <div style={{ textAlign: 'right' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '9px', justifyContent: 'flex-end' }}>
                <span style={{ fontSize: '30px', fontWeight: 600, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums' }}>
                  {config.aggregateScore}
                </span>
                <Stars n={5} />
              </div>
              {config?.aggregateSource ? (
                <div style={{ fontSize: '12px', color: muted, marginTop: '4px' }}>{config.aggregateSource}</div>
              ) : null}
            </div>
          ) : null}
        </div>
      </div>

      <div
        onMouseEnter={function () { if (pauseOnHover) setPaused(true); }}
        onMouseLeave={function () { if (pauseOnHover) setPaused(false); }}
        style={{
          position: 'relative',
          maskImage: edgeFade ? 'linear-gradient(90deg, transparent, #000 90px, #000 calc(100% - 90px), transparent)' : 'none',
          WebkitMaskImage: edgeFade ? 'linear-gradient(90deg, transparent, #000 90px, #000 calc(100% - 90px), transparent)' : 'none'
        }}>
        <div className={uid + '-track'} style={{ animationPlayState: paused ? 'paused' : 'running' }}>
          {cards.map(function (r, i) {
            return (
              <figure key={i} aria-hidden={i >= reviews.length ? 'true' : undefined} style={{
                margin: 0, width: cardW + 'px', flex: '0 0 auto', backgroundColor: card,
                border: '1px solid ' + border, borderRadius: '12px', padding: '22px 22px 20px',
                display: 'flex', flexDirection: 'column', gap: '12px'
              }}>
                <Stars n={r.rating} />
                <blockquote style={{
                  margin: 0, fontSize: quoteSize + 'px', lineHeight: 1.6, color: text
                }}>{r.text}</blockquote>
                <figcaption style={{ marginTop: 'auto', fontSize: '13px' }}>
                  <span style={{ fontWeight: 600 }}>{r.name}</span>
                  {r.meta ? <span style={{ color: muted }}>{' · ' + r.meta}</span> : null}
                </figcaption>
              </figure>
            );
          })}
        </div>
        {reduceMotion ? (
          <p style={{ textAlign: 'center', color: muted, fontSize: '12px', marginTop: '14px' }}>
            Scroll the rail to read more reviews.
          </p>
        ) : null}
      </div>
    </div>
  );
}

