      "showShoppable": { "dataType": "booleanValue", "displayName": "Show Shoppable Tag", "defaultValue": false, "group": "Content" },
      "columns": { "dataType": "select", "displayName": "Columns", "defaultValue": "4", "options": ["2", "3", "4", "5", "6"], "group": "Layout" },
      "rows": { "dataType": "select", "displayName": "Max Rows", "defaultValue": "2", "options": ["1", "2", "3", "all"], "group": "Layout" },
      "gap": { "dataType": "select", "displayName": "Gap (px)", "defaultValue": "8", "options": ["0", "4", "8", "14", "22"], "group": "Layout" },
      "tileRatio": { "dataType": "select", "displayName": "Tile Ratio", "defaultValue": "1/1", "options": ["1/1", "4/5", "3/4", "16/9"], "group": "Layout" },
      "cornerRadius": { "dataType": "select", "displayName": "Corner Radius (px)", "defaultValue": "6", "options": ["0", "4", "6", "12", "20"], "group": "Layout" },
      "hoverEffect": { "dataType": "select", "displayName": "Hover Effect", "defaultValue": "caption", "options": ["caption", "zoom", "engagement", "none"], "group": "Animation" },
      "showEngagement": { "dataType": "booleanValue", "displayName": "Show Likes & Comments", "defaultValue": true, "group": "Animation" },
      "backgroundColor": { "dataType": "color", "displayName": "Background", "defaultValue": "#FFFFFF", "group": "Colors" },
      "textColor": { "dataType": "color", "displayName": "Text", "defaultValue": "#1A1A1A", "group": "Colors" },
      "mutedColor": { "dataType": "color", "displayName": "Muted Text", "defaultValue": "#6B6B6B", "group": "Colors" },
      "accentColor": { "dataType": "color", "displayName": "Accent", "defaultValue": "#1F5450", "group": "Colors" },
      "overlayColor": { "dataType": "color", "displayName": "Hover Overlay", "defaultValue": "#101010", "group": "Colors" },
      "placeholderColor": { "dataType": "color", "displayName": "Tile Placeholder", "defaultValue": "#EFEDE7", "group": "Colors" },
      "headingSize": { "dataType": "number", "displayName": "Heading Size (px)", "defaultValue": 34, "group": "Typography" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config = {} }) {
  const bg = config?.backgroundColor || '#FFFFFF';
  const text = config?.textColor || '#1A1A1A';
  const muted = config?.mutedColor || '#6B6B6B';
  const accent = config?.accentColor || '#1F5450';
  const overlay = config?.overlayColor || '#101010';
  const placeholder = config?.placeholderColor || '#EFEDE7';
  const cols = parseInt(config?.columns || '4', 10);
  const gap = parseInt(config?.gap || '8', 10);
  const radius = parseInt(config?.cornerRadius || '6', 10);
  const ratio = (config?.tileRatio || '1/1').replace('/', ' / ');
  const hoverEffect = config?.hoverEffect || 'caption';
  const showEngagement = config?.showEngagement !== false;
  const showShoppable = config?.showShoppable === true;
  const showFollow = config?.showFollow !== false;
  const headingSize = Math.max(16, Math.min(80, parseInt(config?.headingSize, 10) || 34));
  const rowsSetting = config?.rows || '2';

  const posts = (config?.posts || '').split(';').map(function (chunk) {
    const f = chunk.split('|');
    return {
      image: (f[0] || '').trim(),
      caption: (f[1] || '').trim(),
      likes: (f[2] || '').trim(),
      comments: (f[3] || '').trim(),
      link: (f[4] || '').trim()
    };
  }).filter(function (p) { return p.image; });

  const [hovered, setHovered] = React.useState(null);
  const [isNarrow, setIsNarrow] = React.useState(false);
  const hostRef = React.useRef(null);

  React.useEffect(function () {
    const el = hostRef.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(function (entries) {
      for (const e of entries) setIsNarrow(e.contentRect.width < 680);
    });
    ro.observe(el);
    return function () { ro.disconnect(); };
  }, []);

  const reduceMotion = typeof window !== 'undefined' && window.matchMedia
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

  const effectiveCols = isNarrow ? Math.min(2, cols) : cols;
  const visible = rowsSetting === 'all'
    ? posts
    : posts.slice(0, effectiveCols * parseInt(rowsSetting, 10));

  const fmt = function (v) {
    const n = parseInt(String(v).replace(/[^\d]/g, ''), 10);
    if (isNaN(n)) return v;
    return n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 0 : 1).replace(/\.0$/, '') + 'k' : String(n);
  };

  const Glyph = function (props) {
    const heart = 'M12 21s-7.5-4.7-9.6-9A5.4 5.4 0 0 1 12 5.7 5.4 5.4 0 0 1 21.6 12c-2.1 4.3-9.6 9-9.6 9z';
    const bubble = 'M21 11.5a8.4 8.4 0 0 1-9 8.3 9.3 9.3 0 0 1-3.3-.6L3 21l1.9-5.1A8.2 8.2 0 0 1 3.9 11.5a8.4 8.4 0 0 1 9-8.3 8.4 8.4 0 0 1 8.1 8.3z';
    return (
      <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
        <path d={props.kind === 'like' ? heart : bubble} />
      </svg>
    );
  };

  return (
    <div ref={hostRef} className="instagram-grid" style={{
      backgroundColor: bg, color: text, width: '100%',
      padding: isNarrow ? '54px 18px' : '84px 40px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
      WebkitFontSmoothing: 'antialiased'
    }}>
      <div style={{ maxWidth: '1180px', margin: '0 auto' }}>
        <div style={{
          display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between',
          gap: '20px', flexWrap: 'wrap', marginBottom: '26px'
        }}>
          <div style={{ minWidth: 0 }}>
            {config?.sectionLabel ? (
              <p style={{
                fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: '11px',
                letterSpacing: '0.14em', textTransform: 'uppercase', color: accent, margin: '0 0 10px'
              }}>{config.sectionLabel}</p>
            ) : null}
            {config?.heading ? (
              <h2 style={{
                fontSize: isNarrow ? Math.round(headingSize * 0.76) + 'px' : headingSize + 'px',
                fontWeight: 500, lineHeight: 1.1, letterSpacing: '-0.02em',
                margin: 0, maxWidth: '20ch', textWrap: 'balance'
              }}>{config.heading}</h2>
            ) : null}
          </div>

          {(config?.handle || showFollow) ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
              {config?.handle ? (
                <span style={{ fontSize: '14px', color: muted }}>{config.handle}</span>
              ) : null}
              {showFollow ? (
                <a href={config?.profileUrl || '#'} target="_blank" rel="noopener noreferrer" style={{
                  display: 'inline-flex', alignItems: 'center', gap: '7px', textDecoration: 'none',
                  backgroundColor: accent, color: '#FFFFFF', padding: '10px 17px',
                  borderRadius: '999px', fontSize: '13.5px', fontWeight: 500, whiteSpace: 'nowrap'
                }}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
                    <rect x="3" y="3" width="18" height="18" rx="5" />
                    <circle cx="12" cy="12" r="4" />
                    <circle cx="17.5" cy="6.5" r="1.2" fill="currentColor" stroke="none" />
                  </svg>
                  {config?.followLabel || 'Follow'}
                </a>
              ) : null}
            </div>
          ) : null}
        </div>

        <ul style={{
          listStyle: 'none', margin: 0, padding: 0, display: 'grid',
          gridTemplateColumns: 'repeat(' + effectiveCols + ', minmax(0, 1fr))', gap: gap + 'px'
        }}>
          {visible.map(function (p, i) {
            const on = hovered === i;
            const hasLink = !!p.link;
            const Tag = hasLink ? 'a' : 'div';
            const tagProps = hasLink
              ? { href: p.link, target: '_blank', rel: 'noopener noreferrer' }
              : {};
            return (
              <li key={i} style={{ minWidth: 0 }}>
                <Tag {...tagProps}
                  onMouseEnter={function () { setHovered(i); }}
                  onMouseLeave={function () { setHovered(null); }}
                  onFocus={function () { setHovered(i); }}
                  onBlur={function () { setHovered(null); }}
                  style={{
                    position: 'relative', display: 'block', aspectRatio: ratio,
                    borderRadius: radius + 'px', overflow: 'hidden', backgroundColor: placeholder,
                    textDecoration: 'none', color: 'inherit', maxWidth: '100%',
                    cursor: hasLink ? 'pointer' : 'default'
                  }}>
                  <img src={p.image} alt={p.caption || 'Social post ' + (i + 1)} loading="lazy" style={{
                    width: '100%', height: '100%', objectFit: 'cover', display: 'block',
                    transform: (on && hoverEffect === 'zoom' && !reduceMotion) ? 'scale(1.07)' : 'scale(1)',
                    transition: reduceMotion ? 'none' : 'transform 620ms cubic-bezier(0.22,1,0.36,1)'
                  }} />

                  {hoverEffect !== 'none' ? (
                    <div style={{
                      position: 'absolute', inset: 0, display: 'flex',
                      flexDirection: 'column', justifyContent: 'flex-end', gap: '8px',
                      padding: '14px', color: '#FFFFFF',
                      background: 'linear-gradient(to top, ' + overlay + 'E6, ' + overlay + '00 62%)',
                      opacity: on ? 1 : 0,
                      transition: reduceMotion ? 'none' : 'opacity 260ms ease-out'
                    }}>
                      {(hoverEffect === 'caption' && p.caption) ? (
                        <p style={{ margin: 0, fontSize: '13px', lineHeight: 1.45 }}>{p.caption}</p>
                      ) : null}
                      {(showEngagement && (p.likes || p.comments)) ? (
                        <div style={{ display: 'flex', gap: '14px', fontSize: '12.5px', alignItems: 'center' }}>
                          {p.likes ? (
                            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '5px' }}>
                              <Glyph kind="like" />{fmt(p.likes)}
                            </span>
                          ) : null}
                          {p.comments ? (
                            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '5px' }}>
                              <Glyph kind="comment" />{fmt(p.comments)}
                            </span>
                          ) : null}
                        </div>
                      ) : null}
                    </div>
                  ) : null}

                  {(showShoppable && hasLink) ? (
                    <span style={{
                      position: 'absolute', top: '10px', left: '10px',
                      backgroundColor: '#FFFFFF', color: text, fontSize: '11px', fontWeight: 600,
                      padding: '5px 9px', borderRadius: '999px', letterSpacing: '0.01em'
                    }}>{config?.shoppableLabel || 'Shop this'}</span>
                  ) : null}
                </Tag>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}
